import java.util.*;

class Solution {
  public boolean findSafeWalk(List<List<Integer>> grid, int health) {
    int m = grid.size(), n = grid.get(0).size();
    int[][] cost = new int[m][n];
    for (int[] row : cost) Arrays.fill(row, Integer.MAX_VALUE);
    ArrayDeque<int[]> deque = new ArrayDeque<>();
    cost[0][0] = grid.get(0).get(0);
    deque.offerFirst(new int[] {0, 0});
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    while (!deque.isEmpty()) {
      int[] cell = deque.pollFirst();
      int r = cell[0], c = cell[1];
      for (int z = 0; z < 4; z++) {
        int nr = r + dr[z], nc = c + dc[z];
        if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
        int next = cost[r][c] + grid.get(nr).get(nc);
        if (next < cost[nr][nc] && next < health) {
          cost[nr][nc] = next;
          if (grid.get(nr).get(nc) == 0) deque.offerFirst(new int[] {nr, nc});
          else deque.offerLast(new int[] {nr, nc});
        }
      }
    }
    return cost[m - 1][n - 1] < health;
  }
}
